CREATE OR REPLACE FUNCTION public.refund_1b_is_canonical_period_identity(p_subscription_user_id uuid, p_subscription_id text, p_subscription_membership_plan_id uuid, p_subscription_billing_cycle text, p_term_start timestamp with time zone, p_term_end timestamp with time zone, p_grant_user_id uuid, p_grant_subscription_id text, p_grant_membership_plan_id uuid, p_grant_billing_cycle text, p_grant_type text, p_grant_period_key text, p_grant_period_start timestamp with time zone, p_grant_period_end timestamp with time zone, p_grant_period_index integer, p_grant_total_periods integer, p_grant_stripe_invoice_id text)
